import { NimiqProvider } from './provider.js';
export { ErrorResponse, INimiqProviderConfig, SignatureResult, TransactionInfo } from './provider.js';
import 'events';

/** Read-only host context injected by Nimiq Pay before a Mini App loads. */
interface NimiqPayHostContext {
    readonly language?: string;
    /**
     * Request a pseudonymous, per-origin device identifier (64-char hex SHA-256).
     * Prompts the user on first call per origin; subsequent calls auto-resolve.
     * The identifier is stable across Nimiq Pay reinstalls and across different
     * user accounts on the same device — it identifies the device, not the user.
     * @param options.reason shown verbatim to the user in the consent prompt
     * @throws if the user denies the prompt or if `reason` is empty
     */
    requestDeviceIdentifier: (options: {
        reason: string;
    }) => Promise<string>;
}
declare global {
    interface Window {
        nimiq?: NimiqProvider;
        nimiqPay?: NimiqPayHostContext;
    }
}

interface InitOptions {
    timeout?: number;
}
declare function init(options?: InitOptions): Promise<NimiqProvider>;

/**
 * ISO 639-1 language code selected by the user in Nimiq Pay, or `undefined`
 * when not running inside Nimiq Pay. Seeded synchronously before the Mini
 * App's page script runs, so safe to read during module init.
 */
declare function getHostLanguage(): string | undefined;
/**
 * Request a pseudonymous, per-origin device identifier from Nimiq Pay.
 * Resolves with a 64-char hex SHA-256 string scoped to the Mini App's origin.
 * The identifier is stable across Nimiq Pay reinstalls and across different
 * user accounts on the same device — it identifies the device, not the user.
 * On the first call per origin the user is prompted with `reason`; subsequent
 * calls auto-resolve. Rejects when the user denies the prompt, when `reason`
 * is empty, or when the Mini App is not running inside Nimiq Pay.
 */
declare function requestDeviceIdentifier(options: {
    reason: string;
}): Promise<string>;

export { type InitOptions, type NimiqPayHostContext, NimiqProvider, getHostLanguage, init, requestDeviceIdentifier };
